css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .comp-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 9px 36px;}
.mz .comp-fila{display: flex; align-items: center; gap: 10px; justify-content: center;}
.mz .comp-fila .cn{font-size: 20px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 12px; min-width: 70px; text-align: center;}
.mz .comp-fila .caja-sg{width: 44px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .cumple-fila{display: flex; align-items: center; gap: 12px; font-size: 15px; font-weight: 600; margin-bottom: 7px; flex-wrap: wrap;}
.mz .cumple-fila .pista{flex: 1; line-height: 1.3;}
.mz .cumple-fila .caja-cifra{width: 95px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px; flex-shrink: 0;}
.mz .mm-bloque{display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-bottom: 7px;}
.mz .mm-bloque .gn{font-size: 19px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 4px 14px;}
.mz .mm-resp{display: flex; gap: 22px; margin-top: 4px;}
.mz .mm-resp .casilla{display: flex; align-items: center; gap: 6px; font-size: 14px; font-weight: 600;}
.mz .mm-resp .caja-mm{width: 90px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .banco{display: flex; gap: 10px; margin-bottom: 8px; flex-wrap: wrap;}
.mz .banco .bn{font-size: 19px; font-weight: 700; border: 1.5px dashed #000; border-radius: 8px; padding: 5px 14px; background: #f3f3f3;}
.mz .huecos{display: flex; align-items: center; gap: 8px; flex-wrap: wrap;}
.mz .huecos .hueco-caja{width: 78px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 8px;}
.mz .huecos .flecha{font-size: 18px; font-family: sans-serif;}
